import pandas as pd, glob, os
for threshold in [-60,-120,-300]:
 print('threshold',threshold); out={}
 for f in glob.glob('airlines/*.csv'):
  c=os.path.basename(f)[:2];d=pd.read_csv(f); date='date' if 'date' in d else 'date_utc';s='sched_dep' if 'sched_dep' in d else 'sched_dep_utc';a='actual_dep' if 'actual_dep' in d else 'actual_dep_utc';d=d[d[date].str.startswith('2025-02')].drop_duplicates('flight_id'); ok=~d.cancelled
  mm=lambda x: int(x[:2])*60+int(x[3:]); raw=d.loc[ok,a].map(mm)-d.loc[ok,s].map(mm); delay=raw.where(raw>=threshold,raw+1440)
  out[c]=round((delay>15).sum()/len(delay)*100,1); print(c,(delay>15).sum(),len(delay),out[c])
 print(out)

